(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=1280,H=720,GROUND=563,WORLD=5700;
let scaleX=1,scaleY=1,last=0,started=false,paused=false,gameOver=false,frame=0,camera=0,toastTimer=0,autosave=0;
function resize(){const r=canvas.getBoundingClientRect();const dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);scaleX=canvas.width/W;scaleY=canvas.height/H;ctx.setTransform(scaleX,0,0,scaleY,0,0)}window.addEventListener('resize',resize);resize();
const initial={x:170,y:GROUND,hp:82,stamina:74,hunger:68,thirst:54,temp:31,ammo:8,reserve:24,bandage:2,food:1,water:2,scrap:3,meds:1,xp:40,level:3,weapon:'SERVICE PISTOL',kills:0,found:[],choice:null,step:0,visited:[],day:6};
let state={...initial};try{const saved=JSON.parse(localStorage.getItem('ashes-save'));if(saved)state={...initial,...saved}}catch{}
const player={x:state.x,y:GROUND,vx:0,vy:0,w:34,h:65,facing:1,onGround:true,invuln:0,attack:0,walk:0};
let keys={},mouse={x:W*.7,y:H*.5,down:false},bullets=[],enemyBullets=[],particles=[],enemies=[],interactables=[];
const regions=[{x:0,name:'THE QUIET MILE',weather:'ACID RAIN',sky:'#263936'},{x:1120,name:'THE WILLOW LINE',weather:'LOW FOG',sky:'#26372e'},{x:2440,name:'NORTH CHECKPOINT',weather:'DUST STORM',sky:'#3b3329'},{x:3720,name:'THE BLACKSITE',weather:'COLD DRIZZLE',sky:'#283139'},{x:4930,name:'BENEATH THE CITY',weather:'CONDENSATION',sky:'#202a2a'}];
const props=[{x:440,type:'car'},{x:665,type:'relay'},{x:1030,type:'bus'},{x:1350,type:'tree'},{x:1540,type:'tree'},{x:1780,type:'cabin'},{x:2100,type:'tree'},{x:2590,type:'checkpoint'},{x:2960,type:'truck'},{x:3230,type:'barrel'},{x:3950,type:'lab'},{x:4500,type:'tree'},{x:5180,type:'metro'}];
function mkEnemy(x,type='infected'){enemies.push({x,y:GROUND,w:type==='mutant'?48:32,h:type==='mutant'?75:61,type,hp:type==='mutant'?105:type==='soldier'?75:55,speed:type==='mutant'?34:type==='soldier'?25:40,dir:-1,attack:0,alert:0,dead:false,phase:Math.random()*6})}
mkEnemy(920);mkEnemy(1260);mkEnemy(1970);mkEnemy(2700,'soldier');mkEnemy(2890,'soldier');mkEnemy(3420,'mutant');mkEnemy(4220);mkEnemy(4670,'mutant');
interactables=[{x:690,type:'relay',name:'EMERGENCY RELAY',icon:'⌁',radius:68},{x:1080,type:'cache',name:'ABANDONED FIELD PACK',icon:'▣',radius:55},{x:1800,type:'survivor',name:'ELI — WANDERING MEDIC',icon:'◉',radius:68},{x:2660,type:'checkpoint',name:'MILITARY CHECKPOINT',icon:'⚑',radius:70},{x:3250,type:'cache',name:'QUARTERMASTER CRATE',icon:'▣',radius:58},{x:4020,type:'lab',name:'BLACKSITE ACCESS',icon:'⌑',radius:75},{x:4780,type:'cache',name:'SEALED SUPPLY CASE',icon:'▣',radius:55},{x:5230,type:'sample',name:'CONTAINMENT VAULT',icon:'◈',radius:80}];
const el=id=>document.getElementById(id);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function save(){state.x=player.x;try{localStorage.setItem('ashes-save',JSON.stringify(state));el('saveStatus').innerHTML='●&nbsp; FIELD LOG SYNCED';setTimeout(()=>{if(el('saveStatus'))el('saveStatus').innerHTML='●&nbsp; FIELD LOG SYNCED'},500)}catch{}}
function notify(msg){const t=el('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function setObjective(title,text,objective,step){el('questTitle').textContent=title;el('questText').textContent=text;el('objectiveText').textContent=objective;el('questProgress').style.width=step===0?'18%':step===1?'42%':step===2?'66%':step===3?'86%':'100%';el('objectiveCheck').classList.toggle('done',step>state.step);}
function updateQuest(){const s=state.step;if(s===0)setObjective('A SIGNAL IN THE STATIC','A voice cuts through the emergency band. Find where it comes from.','Reach the old relay station',s);if(s===1)setObjective('A VOICE IN THE DARK','The signal carried a name: Blacksite. Find someone who knows the road.','Speak with the wandering medic',s);if(s===2)setObjective('NO SAFE PASSAGE','A military checkpoint blocks the road. Search for a way through.','Reach the North checkpoint',s);if(s===3)setObjective('THE BLACKSITE','The broadcast was no accident. Find the underground facility.','Enter the Blacksite access',s);if(s===4)setObjective('PATIENT ZERO','The source is below. Recover the truth — then choose what survives.','Reach the containment vault',s);if(s>=5)setObjective('ASHES OF TOMORROW','Some truths cannot be buried.','The ending is yours to carry',s)}
function startGame(){started=true;el('titleScreen')?.classList.add('hidden');if(state.step===0&&state.x>170)state.x=170;player.x=state.x;notify('FIELD LOG: DAY 06 — KEEP MOVING');save();}
function showModal(content){paused=true;const o=el('screenOverlay');o.classList.add('open');el('modal').innerHTML=content;}
function closeModal(){el('screenOverlay').classList.remove('open');paused=false;}
function panelButton(text,action,secondary=''){return `<button class="action-btn ${secondary}" data-action="${action}">${text}</button>`}
function openPanel(type){if(type==='inventory')inventoryPanel();else if(type==='journal')journalPanel();else if(type==='map')mapPanel();}
function inventoryPanel(){const items=[['◉','PURIFIED WATER','Restore thirst',state.water],['◒','CANNED FOOD','Restore hunger',state.food],['✚','FIELD DRESSING','Restore health',state.bandage],['⌁','9MM AMMUNITION','Pistol rounds',state.reserve],['◇','SCRAP METAL','Crafting material',state.scrap],['✣','MEDICAL SUPPLIES','Medical components',state.meds]];showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">FIELD KIT · CARRIED LOAD 6.4 KG</div><h1>INVENTORY</h1><p>What you carry is all that remains. Resources are scarce; choose carefully.</p><div class="modal-grid">${items.map(i=>`<div class="item-card"><span class="item-symbol">${i[0]}</span><div><strong>${i[1]}</strong><small>${i[2]}</small></div><span class="item-count">${String(i[3]).padStart(2,'0')}</span></div>`).join('')}</div><div class="modal-kicker">FIELD CRAFTING</div><p>Combine what you find. Improvised tools won't last forever.</p><div class="modal-actions">${panelButton('CRAFT BANDAGE · 2 SCRAP','craft-bandage')}${panelButton('CRAFT AMMO · 2 SCRAP','craft-ammo')}${panelButton('CHARACTER · LVL 03','stats','secondary')}</div>`)}
function journalPanel(){const pages=[['06 OCT 2041 — OUTER DISTRICT','The rain has a metallic taste again. The emergency band is still live. Someone keeps repeating the same coordinates.'],['THE SIGNAL','A clipped transmission: “...Blacksite... patient zero... don’t let them burn the archive...” The voice sounded young.'],['THE QUESTION','If a cure exists, who gets it? The people who can pay? The people who can carry it? Or no one at all?']];showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">MARA REYES · PERSONAL RECORD</div><h1>FIELD JOURNAL</h1><div class="story-line"><span class="modal-kicker">${pages[Math.min(state.step,2)][0]}</span><p>${pages[Math.min(state.step,2)][1]}</p></div><div class="modal-kicker">MISSIONS</div><div class="item-card"><span class="item-symbol">◆</span><div><strong>${el('questTitle').textContent}</strong><small>${el('objectiveText').textContent}</small></div><span class="item-count">${state.step>=5?'✓':'…'}</span></div><div class="modal-actions">${panelButton('CHARACTER STATISTICS','stats')}${panelButton('CLOSE','close','secondary')}</div>`)}
function statsPanel(){showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">SURVIVOR PROFILE · DAY 06</div><h1>CHARACTER</h1><p>Mara Reyes · Scavenger · Level 03</p><div class="modal-grid"><div class="item-card"><div><strong>COMBAT</strong><small>${state.kills} hostile threats neutralized</small></div></div><div class="item-card"><div><strong>EXPERIENCE</strong><small>${state.xp} / 100 XP</small></div></div><div class="item-card"><div><strong>CONDITION</strong><small>${Math.round(state.hp)}% health · ${Math.round(state.stamina)}% stamina</small></div></div><div class="item-card"><div><strong>DISCOVERIES</strong><small>${state.found.length} locations documented</small></div></div></div><div class="modal-actions">${panelButton('BACK','inventory')}</div>`)}
function mapPanel(){showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">HAND-DRAWN · NOT TO SCALE</div><h1>THE OUTER DISTRICT</h1><p>Signal strength fades beyond the old city limits. Marked locations are not guaranteed safe.</p><div class="map-board"><span class="map-label" style="left:4%;top:70%">QUIET MILE</span><span class="map-label" style="left:25%;top:18%">WILLOW LINE</span><span class="map-label" style="left:44%;top:70%">CHECKPOINT</span><span class="map-label" style="left:70%;top:18%">BLACKSITE</span><span class="map-label" style="left:79%;top:76%">CONTAINMENT</span><i class="map-marker" style="left:${clamp(player.x/WORLD*92+4,4,94)}%;top:48%">⌖</i><i class="map-node" style="left:12%;top:54%"></i><i class="map-node" style="left:45%;top:60%"></i><i class="map-node" style="left:72%;top:39%"></i></div><p><span class="ending">⌖</span> YOUR POSITION &nbsp; · &nbsp; <span style="color:#bc8b6a">●</span> HOSTILE ZONE</p><div class="modal-actions">${panelButton('CLOSE MAP','close','secondary')}</div>`)}

