// distant broken skyline
for(let i=0;i<12;i++){let x=((i*139-camera*.3)%1500+1500)%1500-80;let h=90+(i*47)%180;ctx.fillStyle=i%2?'#303b35':'#364039';ctx.fillRect(x,GROUND-h,94,h);ctx.fillStyle='#41463a';ctx.fillRect(x-5,GROUND-h,104,8);ctx.fillStyle='rgba(14,22,20,.48)';for(let y=GROUND-h+20;y<GROUND-24;y+=26)for(let wx=x+12;wx<x+83;wx+=21)if(((wx+y+i)%3)<2)ctx.fillRect(wx,y,9,13)}
// atmospheric rays
ctx.save();ctx.globalAlpha=.12;ctx.fillStyle='#c9c4a4';ctx.beginPath();ctx.moveTo(680,0);ctx.lineTo(720,0);ctx.lineTo(540,GROUND);ctx.lineTo(340,GROUND);ctx.fill();ctx.restore()}
function drawGround(){const g=ctx.createLinearGradient(0,GROUND,0,H);g.addColorStop(0,'#3b4034');g.addColorStop(.08,'#292f28');g.addColorStop(1,'#111816');ctx.fillStyle=g;ctx.fillRect(0,GROUND,W,H-GROUND);line(0,GROUND,W,GROUND,'#a0a17a66',2);for(let i=0;i<50;i++){const x=((i*79-camera*.92)%1400+1400)%1400-50;const y=GROUND+8+(i*31)%150;line(x,y,x+12+(i%6)*3,y-1,'#77766033',1)}for(let i=0;i<19;i++){const x=((i*87-camera*.75)%1400+1400)%1400-40;const h=6+(i*13)%16;ctx.fillStyle=i%3?'#131a17':'#514c3c';ctx.fillRect(x,GROUND+18+(i*19)%120,8+(i%5)*7,h)}ctx.fillStyle='#171d19';ctx.fillRect(0,GROUND-2,W,4)}
