function drawEffects(dt){const reg=[...regions].reverse().find(r=>player.x>=r.x)||regions[0];const isRain=reg.name==='THE QUIET MILE'||reg.name==='THE BLACKSITE';ctx.save();if(isRain){ctx.strokeStyle='rgba(188,204,194,.22)';ctx.lineWidth=1;for(let i=0;i<95;i++){let x=(i*173+frame*11)%W,y=(i*97+frame*17)%H;line(x,y,x-9,y+19,'rgba(188,204,194,.22)',1)}}else if(reg.name==='THE WILLOW LINE'){for(let i=0;i<14;i++){const x=((i*103+frame*.6)%W),y=100+(i*61)%420;ctx.fillStyle='rgba(206,211,197,.035)';ctx.beginPath();ctx.ellipse(x,y,95,20,0,0,7);ctx.fill()}}else if(reg.name==='NORTH CHECKPOINT'){ctx.fillStyle='rgba(157,122,79,.08)';ctx.fillRect(0,0,W,H);ctx.strokeStyle='rgba(202,176,132,.15)';for(let i=0;i<40;i++){const x=(i*83+frame*2)%W,y=(i*47+frame)%H;line(x,y,x+14,y-2,'rgba(202,176,132,.15)',1)}}ctx.restore();for(const p of particles){ctx.globalAlpha=p.life;ctx.fillStyle=p.color;ctx.fillRect(worldX(p.x),p.y,p.size,p.size);ctx.globalAlpha=1}for(const b of bullets){const sx=worldX(b.x);ctx.strokeStyle='#f0d291';ctx.shadowBlur=8;ctx.shadowColor='#f3c76e';line(sx,b.y,sx-b.dir*16,b.y,'#f1cc7d',2);ctx.shadowBlur=0}for(const b of enemyBullets){const sx=worldX(b.x);ctx.fillStyle='#d78960';ctx.fillRect(sx-3,b.y-2,7,4)}}
function render(){ctx.clearRect(0,0,W,H);camera=clamp(player.x-440,0,WORLD-W);drawSky();drawGround();drawProps();for(const e of enemies)drawEnemy(e);drawPlayer();drawEffects(0);const region=[...regions].reverse().find(r=>player.x>=r.x)||regions[0];el('locationName').textContent=region.name;el('weatherName').textContent=region.weather;const near=interactables.find(i=>!i.used&&Math.abs(i.x-player.x)<i.radius);el('interactionPrompt').classList.toggle('show',!!near&&started&&!paused);el('interactionPrompt').innerHTML=near?`<kbd>E</kbd><span>${near.name}</span>`:'';el('distance').textContent=state.step<5?`${Math.max(0,Math.round((([690,1800,2660,4020,5230][state.step]||0)-player.x)/10))} M`:'COMPLETE';}

