function render(){ctx.clearRect(0,0,W,H);camera=clamp(player.x-440,0,WORLD-W);drawSky();drawGround();drawProps();for(const e of enemies)drawEnemy(e);drawPlayer();drawEffects(0);const region=[...regions].reverse().find(r=>player.x>=r.x)||regions[0];el('locationName').textContent=region.name;el('weatherName').textContent=region.weather;const target=[690,1800,2660,4020,5230][state.step];const near=interactables.find(i=>!i.used&&Math.abs(i.x-player.x)<i.radius);el('interactionPrompt').classList.toggle('show',!!near&&started&&!paused);el('interactionPrompt').innerHTML=near?`<kbd>E</kbd><span>${near.name}</span>`:'';el('distance').textContent=state.step<5?`${Math.max(0,Math.round(Math.abs(target-player.x)/10))} M`:'COMPLETE';}
function addParticle(x,y,color='#b5aa86',size=3,vx=0,vy=-30){particles.push({x,y,color,size,vx,vy,life:.45+Math.random()*.4})}
function updateHud(){for(const [id,val] of [['health',state.hp],['stamina',state.stamina]]){el(id+'Num').textContent=Math.round(val);el(id+'Fill').style.width=clamp(val,0,100)+'%'}for(const [name,val] of [['hunger',state.hunger],['thirst',state.thirst]]){el(name+'Num').textContent=Math.round(val);el(name+'Fill').style.width=clamp(val,0,100)+'%'}el('tempNum').textContent=`${Math.round(state.temp)}°`;el('tempFill').style.width=clamp((state.temp-15)*4,0,100)+'%';el('ammoCount').textContent=String(state.ammo).padStart(2,'0');el('reserveAmmo').textContent=String(state.reserve).padStart(2,'0');el('bandageCount').textContent=state.bandage;el('foodCount').textContent=state.food;el('waterCount').textContent=state.water;el('healthFill').style.background=state.hp<30?'#e04839':'';}
function damage(amount,source=''){if(player.invuln>0)return;state.hp=Math.max(0,state.hp-amount);player.invuln=1.1;for(let i=0;i<8;i++)addParticle(player.x,player.y-35,'#a94e3d',3,(Math.random()-.5)*100,-Math.random()*65);notify(source?`HIT — ${source}`:'WOUNDED');if(state.hp<=0){gameOver=true;showModal(`<div class="modal-kicker">DAY 06 · OUTER DISTRICT</div><h1>THE WORLD GOES QUIET</h1><p>Mara's field log ends here. The signal continues to transmit into the rain.</p><div class="modal-actions">${panelButton('LOAD LAST SAVE','restart')}${panelButton('RETURN TO TITLE','title','secondary')}</div>`)}updateHud()}
function melee(){if(player.attack>0||state.stamina<9)return;player.attack=.32;state.stamina-=9;let hit=false;for(const e of enemies){if(e.dead||Math.abs(e.x-player.x)>73||Math.sign(e.x-player.x)!==player.facing)continue;e.hp-=40;hit=true;for(let i=0;i<7;i++)addParticle(e.x,e.y-35,'#aa654f',3,(Math.random()-.5)*90,-Math.random()*70);if(e.hp<=0)killEnemy(e)}if(hit)notify('KNIFE STRIKE');else notify('KNIFE SWING');}
function shoot(){if(state.ammo<=0){notify('EMPTY — PRESS R TO RELOAD');return}if(player.attack>0)return;state.ammo--;player.attack=.18;const targetX=camera+mouse.x,targetY=mouse.y;const dx=targetX-player.x,dy=targetY-(player.y-39),dist=Math.max(1,Math.hypot(dx,dy)),dir=Math.sign(dx)||player.facing;player.facing=dir;bullets.push({x:player.x+dir*27,y:player.y-39,vx:dx/dist*840,vy:dy/dist*840,dir,life:1.15});for(let i=0;i<3;i++)addParticle(player.x+dir*32,player.y-39,'#e1b979',2,(Math.random()-.5)*50,-20-Math.random()*35);updateHud()}
function killEnemy(e){e.dead=true;e.fade=0;state.kills++;state.xp+=20;state.scrap+=Math.random()<.55?1:0;notify('THREAT NEUTRALIZED  +20 XP');if(state.xp>=100&&state.level===3){state.level++;state.hp=Math.min(100,state.hp+18);notify('LEVEL 04 — FIELD HARDENED')}for(let i=0;i<13;i++)addParticle(e.x,e.y-27,'#835143',3,(Math.random()-.5)*95,-Math.random()*75);}
function interact(){const i=interactables.find(a=>!a.used&&Math.abs(a.x-player.x)<a.radius);if(!i){notify('NOTHING WITHIN REACH');return}if(i.type==='relay'){if(state.step===0){i.used=true;state.step=1;state.xp+=20;updateQuest();notify('SIGNAL LOGGED — BLACKSITE / NORTH 09');showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">EMERGENCY BROADCAST · 17:42 UTC</div><h1>A VOICE IN THE STATIC</h1><div class="story-line">“...North 09. The subjects aren't dead. I repeat, they are not dead. If you can hear this, find the medic at the east treeline. The Directorate—”<br><br><span class="ending">[TRANSMISSION LOST]</span></div><p>The signal ends in a burst of static. Someone out there knows what happened here.</p><div class="modal-actions">${panelButton('CONTINUE','close')}</div>`)}else notify('THE RELAY IS SILENT')}else if(i.type==='cache'){i.used=true;const take=i.x<1200?['ammo']:i.x<3500?['supplies']:['meds'];if(take[0]==='ammo'){state.reserve+=12;state.bandage++;notify('FIELD PACK: +12 ROUNDS · +1 BANDAGE')}else if(take[0]==='supplies'){state.scrap+=3;state.food++;notify('SUPPLIES FOUND: +3 SCRAP · +1 FOOD')}else{state.meds+=2;state.water++;notify('SEALED CASE: +2 MEDS · +1 WATER')}state.xp+=10;updateHud();save()}else if(i.type==='survivor'){if(state.step===1){i.used=true;state.step=2;state.meds++;state.bandage++;updateQuest();showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">WILLOW LINE · 17:58</div><h1>THE WANDERING MEDIC</h1><p>“Eli. I used to patch people up for the county. Now I patch whoever doesn't point a gun at me.”</p><div class="story-line">He studies the coordinates you copied from the relay. “North checkpoint. There were soldiers there before the fall. If they're still there, don't let them take you alive. The facility is real. I saw what they brought in.”</div><p>Eli gives you a field dressing and medical supplies, then turns back toward the trees.</p><div class="modal-actions">${panelButton('TAKE THE ROAD NORTH','close')}</div>`);save()}else if(state.step<1)notify('THE MEDIC IS WATCHING THE ROAD');else notify('ELI HAS MOVED ON')}else if(i.type==='checkpoint'){if(state.step===2){showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">NORTH CHECKPOINT · 18:31</div><h1>NO SAFE PASSAGE</h1><p>Two soldiers have fortified the road. They haven't seen you yet.</p><div class="story-line">You could make a run for the broken culvert in the storm, or fight your way through. Either way, there's no going back.</div><div class="modal-actions">${panelButton('SNEAK THROUGH · -20 STAMINA','sneak')}${panelButton('FIGHT · THEY WILL REMEMBER','fight','secondary')}</div>`)}else if(state.step<2)notify('A MILITARY BARRICADE BLOCKS THE ROAD');else notify('THE CHECKPOINT IS ABANDONED')}else if(i.type==='lab'){if(state.step===3){i.used=true;state.step=4;updateQuest();state.xp+=20;showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">NORTH 09 · RESTRICTED ACCESS</div><h1>THE BLACKSITE</h1><div class="story-line">The door groans open. Behind it: a subterranean lab, abandoned in a hurry. The wall is covered in evacuation marks. Every name has been crossed out — except one: E. VALE.</div><p>A stairwell descends into the dark. Your radio crackles: “Mara? If you find the vault, don't let them release it. Please.” A voice you recognize from the broadcast.</p><div class="modal-actions">${panelButton('DESCEND','close')}</div>`);save()}else notify('SEALED — AUTHORIZATION REQUIRED')}else if(i.type==='sample'){if(state.step===4){i.used=true;state.step=5;updateQuest();showEndingChoice()}else if(state.step<4)notify('THE VAULT IS SEALED')}save();updateHud()}
function showEndingChoice(){showModal(`<div class="modal-kicker">CONTAINMENT VAULT · 19:06</div><h1>WHAT REMAINS</h1><div class="story-line">Inside the vault: a single viable culture. The infection wasn't a weapon. The Directorate tried to engineer immunity from it — and made the world sick. A cure could save thousands. It could also become the next weapon.</div><p>The radio wakes. Eli's voice: “Whatever you do with it, make sure it doesn't happen again.” There are no clean choices left.</p><div class="modal-actions">${panelButton('RELEASE THE CURE · SHARE IT','ending-cure')}${panelButton('DESTROY THE CULTURE · NO MORE WEAPONS','ending-destroy','secondary')}${panelButton('KEEP IT · DECIDE LATER','ending-keep','secondary')}</div>`)}

