tions">${panelButton('TAKE THE ROAD NORTH','close')}</div>`);save()}else if(state.step<1)notify('THE MEDIC IS WATCHING THE ROAD');else notify('ELI HAS MOVED ON')}else if(i.type==='checkpoint'){if(state.step===2){showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">NORTH CHECKPOINT · 18:31</div><h1>NO SAFE PASSAGE</h1><p>Two soldiers have fortified the road. They haven't seen you yet.</p><div class="story-line">You could make a run for the broken culvert in the storm, or fight your way through. Either way, there's no going back.</div><div class="modal-actions">${panelButton('SNEAK THROUGH · -20 STAMINA','sneak')}${panelButton('FIGHT · THEY WILL REMEMBER','fight','secondary')}</div>`)}else if(state.step<2)notify('A MILITARY BARRICADE BLOCKS THE ROAD');else notify('THE CHECKPOINT IS ABANDONED')}else if(i.type==='lab'){if(state.step===3){i.used=true;state.step=4;updateQuest();state.xp+=20;showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">NORTH 09 · RESTRICTED ACCESS</div><h1>THE BLACKSITE</h1><div class="story-line">The door groans open. Behind it: a subterranean lab, abandoned in a hurry. The wall is covered in evacuation marks. Every name has been crossed out — except one: E. VALE.</div><p>A stairwell descends into the dark. Your radio crackles: “Mara? If you find the vault, don't let them release it. Please.” A voice you recognize from the broadcast.</p><div class="modal-actions">${panelButton('DESCEND','close')}</div>`);save()}else notify('SEALED — AUTHORIZATION REQUIRED')}else if(i.type==='sample'){if(state.step===4){i.used=true;state.step=5;updateQuest();showEndingChoice()}else if(state.step<4)notify('THE VAULT IS SEALED')}save();updateHud()}
