function interact(){const i=interactables.find(a=>!a.used&&Math.abs(a.x-player.x)<a.radius);if(!i){notify('NOTHING WITHIN REACH');return}if(i.type==='relay'){if(state.step===0){i.used=true;state.step=1;state.xp+=20;updateQuest();notify('SIGNAL LOGGED — BLACKSITE / NORTH 09');showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">EMERGENCY BROADCAST · 17:42 UTC</div><h1>A VOICE IN THE STATIC</h1><div class="story-line">“...North 09. The subjects aren't dead. I repeat, they are not dead. If you can hear this, find the medic at the east treeline. The Directorate—”<br><br><span class="ending">[TRANSMISSION LOST]</span></div><p>The signal ends in a burst of static. Someone out there knows what happened here.</p><div class="modal-actions">${panelButton('CONTINUE','close')}</div>`)}else notify('THE RELAY IS SILENT')}else if(i.type==='cache'){i.used=true;const take=i.x<1200?['ammo']:i.x<3500?['supplies']:['meds'];if(take[0]==='ammo'){state.reserve+=12;state.bandage++;notify('FIELD PACK: +12 ROUNDS · +1 BANDAGE')}else if(take[0]==='supplies'){state.scrap+=3;state.food++;notify('SUPPLIES FOUND: +3 SCRAP · +1 FOOD')}else{state.meds+=2;state.water++;notify('SEALED CASE: +2 MEDS · +1 WATER')}state.xp+=10;updateHud();save()}else if(i.type==='survivor'){if(state.step===1){i.used=true;state.step=2;state.meds++;state.bandage++;updateQuest();showModal(`<button class="modal-close" data-action="close">×</button><div class="modal-kicker">WILLOW LINE · 17:58</div><h1>THE WANDERING MEDIC</h1><p>“Eli. I used to patch people up for the county. Now I patch whoever doesn't point a gun at me.”</p><div class="story-line">He studies the coordinates you copied from the relay. “North checkpoint. There were soldiers there before the fall. If they're still there, don't let them take you alive. The facility is real. I saw what they brought in.”</div><p>Eli gives you a field dressing and medical supplies, then turns back toward the trees.</p><div class="modal-ac