function showEndingChoice(){showModal(`<div class="modal-kicker">CONTAINMENT VAULT · 19:06</div><h1>WHAT REMAINS</h1><div class="story-line">Inside the vault: a single viable culture. The infection wasn't a weapon. The Directorate tried to engineer immunity from it — and made the world sick. A cure could save thousands. It could also become the next weapon.</div><p>The radio wakes. Eli's voice: “Whatever you do with it, make sure it doesn't happen again.” There are no clean choices left.</p><div class="modal-actions">${panelButton('RELEASE THE CURE · SHARE IT','ending-cure')}${panelButton('DESTROY THE CULTURE · NO MORE WEAPONS','ending-destroy','secondary')}${panelButton('KEEP IT · DECIDE LATER','ending-keep','secondary')}</div>`)}
function doEnding(kind){state.choice=kind;const copy=kind==='cure'?['A PROMISE IN THE RUINS','You transmit the formula on every surviving frequency. Within weeks, the first clinics are lit again. Eli is among the first to answer. The cure is no guarantee of peace — but people begin to choose one another.']:kind==='destroy'?['NO SECOND DAWN','You break the vial against the concrete and burn the archive. There will be no cure, and no one will ever use it as a weapon. Eli does not answer your radio. You keep walking anyway.']:['THE WEIGHT OF TOMORROW','You lock the culture in the vault and carry the only key. No one gets to decide today. Not the Directorate. Not Eli. Not even you. The road ahead is long.'];state.xp+=40;state.found.push('Containment Vault');showModal(`<div class="modal-kicker">ASHES OF TOMORROW · ENDING ${kind.toUpperCase()}</div><h1>${copy[0]}</h1><p>${copy[1]}</p><div class="story-line">MARA REYES · SURVIVED TO DAY 06 · ${state.kills} THREATS NEUTRALIZED · LEVEL ${state.level}</div><div class="modal-actions">${panelButton('CONTINUE EXPLORING','close')}${panelButton('RETURN TO TITLE','title','secondary')}</div>`);save()}
