function update(dt){frame++;if(!started||paused)return;dt=Math.min(dt,.035);player.invuln=Math.max(0,player.invuln-dt);player.attack=Math.max(0,player.attack-dt);const left=keys.a||keys.arrowleft,right=keys.d||keys.arrowright;let direction=(right?1:0)-(left?1:0);if(direction){player.facing=direction;player.vx=direction*205;player.walk+=dt*10}else{player.vx*=Math.pow(.001,dt);player.walk*=.8}if((keys.space||keys.w||keys.arrowup)&&player.onGround){player.vy=-410;player.onGround=false;keys.space=false;keys.w=false;keys.arrowup=false}if(keys.shift&&direction&&state.stamina>0){player.vx=direction*295;state.stamina=Math.max(0,state.stamina-dt*14)}else state.stamina=Math.min(100,state.stamina+dt*9);player.vy+=960*dt;player.x=clamp(player.x+player.vx*dt,35,WORLD-35);player.y+=player.vy*dt;if(player.y>=GROUND){player.y=GROUND;player.vy=0;player.onGround=true}state.hunger=Math.max(0,state.hunger-dt*.17);state.thirst=Math.max(0,state.thirst-dt*.28);state.temp=Math.max(22,state.temp-dt*.012);if(state.hunger<12||state.thirst<12)state.hp=Math.max(0,state.hp-dt*.38);if(state.hp<=0&&!gameOver)endGame();for(const e of enemies){if(e.dead){e.fade+=dt;continue}const dx=player.x-e.x,dist=Math.abs(dx);if(dist<410)e.alert=Math.min(1,e.alert+dt*1.7);else e.alert=Math.max(0,e.alert-dt*.15);if(e.alert>.4&&dist>50&&!(e.type==='soldier'&&dist<280)){e.dir=Math.sign(dx);e.x+=e.dir*e.speed*dt*(e.alert>.8?1.3:1)}e.attack=Math.max(0,e.attack-dt);if(e.type==='soldier'&&e.alert>.65&&dist<290&&e.attack<=0){enemyBullets.push({x:e.x,y:e.y-39,vx:Math.sign(dx)*310,life:1});e.attack=1.5}else if(dist<50&&e.attack<=0){damage(e.type==='mutant'?19:e.type==='soldier'?11:9,e.type==='mutant'?'MUTANT':e.type==='soldier'?'GUNFIRE':'INFECTED');e.attack=e.type==='mutant'?1.3:1.55}}for(let n=bullets.length-1;n>=0;n--){const b=bullets[n];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;let hit=false;for(const e of enemies){if(e.dead)continue;if(Math.abs(e.x-b.x)<(e.type==='mutant'?25:18)&&b.y>GROUND-e.h&&b.y<GROUND-10){e.hp-=e.typ