function pauseGame(){if(!started||gameOver)return;if(paused){closeModal();return}showModal(`<button class="modal-close" data-action="resume">×</button><div class="modal-kicker">FIELD LOG · DAY 06</div><h1>PAUSED</h1><p>The rain keeps falling. Take a moment, survivor.</p><div class="modal-actions">${panelButton('RESUME','resume')}${panelButton('INVENTORY','inventory','secondary')}${panelButton('SAVE FIELD LOG','save','secondary')}${panelButton('RETURN TO TITLE','title','secondary')}</div>`)}
