(async()=>{
 const browser=await chromium.connectOverCDP('http://127.0.0.1:9222');
 const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true});
 const page=await context.newPage();
 await page.route('**/game.js',async route=>{const response=await route.fetch();const source=await response.text();await route.fulfill({response,body:source.replace(/\}\)\(\);\s*$/,'window.__gameTest=()=>({x:player.x,y:player.y,onGround:player.onGround,ammo:state.ammo,step:state.step});})();')})});
 await page.goto('http://127.0.0.1:8765');
 await page.locator('#startBtn').click();
 const cdp=await context.newCDPSession(page);
 async function touch(id,duration=70){const b=await page.locator(`#${id}`).boundingBox();const x=b.x+b.width/2,y=b.y+b.height/2;await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x,y,id:1}]});await page.waitForTimeout(duration);const state=await page.evaluate(()=>window.__gameTest());await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await page.waitForTimeout(80);return {state,button:b}}
 const beforeJump=await page.evaluate(()=>window.__gameTest());const jump=await touch('touchJump',110);const afterJump=await page.evaluate(()=>window.__gameTest());
 const beforeFire=afterJump.ammo;await touch('touchFire',40);const afterFire=await page.evaluate(()=>window.__gameTest());
 await page.evaluate(()=>{const t=window.__gameTest; /* diagnostics only */});
 // Put the player beside Eli to verify the dedicated touch-use button invokes interaction.
 await page.evaluate(()=>{const canvas=document.querySelector('#game');canvas.dispatchEvent(new Event('test'))});
 // Player/state live in the game closure; exercise the control in its live proximity with a seeded reload.
 await page.evaluate(()=>{localStorage.setItem('ashes-save',JSON.stringify({x:1800,hp:82,stamina:74,hunger:68,thirst:54,temp:31,ammo:8,reserve:24,bandage:2,food:1,water:2,scrap:3,meds:1,xp:40,level:3,weapon:'SERVICE PISTOL',kills:0,found:[],choice:null,step:1,visited:[],used:[],day:6}))});
 await page.reload();await page.waitForFunction(()=>window.__gameTest);await page.locator('#continueBtn').click();await touch('touchUse',40);const interaction=await page.locator('#modal').innerText();
 console.log(JSON.stringify({jump:{before:beforeJump,whileHeld:jump.state,after:afterJump},fire:{beforeAmmo:beforeFire,afterAmmo:afterFire.ammo},interaction:interaction.includes('THE WANDERING MEDIC'),interactionText:interaction.slice(0,120),jumpButton:jump.button},null,2));
 await context.close();await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

