66:function showEndingChoice(){showModal(`<div class="modal-kicker">CONTAINMENT VAULT · 19:06</div><h1>WHAT REMAINS</h1><div class="story-line">Inside the vault: a single viable culture. The infection wasn't a weapon. The Directorate tried to engineer immunity from it — and made the world sick. A cure could save thousands. It could also become the next weapon.</div><p>The radio wakes. Eli's voice: “Whatever you do with it, make sure it doesn't happen again.” There are no clean choices left.</p><div class="modal-actions">${panelButton('RELEASE THE CURE · SHARE IT','ending-cure')}${panelButton('DESTROY THE CULTURE · NO MORE WEAPONS','ending-destroy','secondary')}${panelButton('KEEP IT · DECIDE LATER','ending-keep','secondary')}</div>`)}
67:function doEnding(kind){state.choice=kind;const copy=kind==='cure'?['A PROMISE IN THE RUINS','You transmit the formula on every surviving frequency. Within weeks, the first clinics are lit again. Eli is among the first to answer. The cure is no guarantee of peace — but people begin to choose one another.']:kind==='destroy'?['NO SECOND DAWN','You break the vial against the concrete and burn the archive. There will be no cure, and no one will ever use it as a weapon. Eli does not answer your radio. You keep walking anyway.']:['THE WEIGHT OF TOMORROW','You lock the culture in the vault and carry the only key. No one gets to decide today. Not the Directorate. Not Eli. Not even you. The road ahead is long.'];state.xp+=40;state.found.push('Containment Vault');showModal(`<div class="modal-kicker">ASHES OF TOMORROW · ENDING ${kind.toUpperCase()}</div><h1>${copy[0]}</h1><p>${copy[1]}</p><div class="story-line">MARA REYES · SURVIVED TO DAY 06 · ${state.kills} THREATS NEUTRALIZED · LEVEL ${state.level}</div><div class="modal-actions">${panelButton('CONTINUE EXPLORING','close')}${panelButton('RETURN TO TITLE','title','secondary')}</div>`);save()}
68:function performAction(action){if(action==='close'){closeModal();return}if(action==='inventory'){inventoryPanel();return}if(action==='stats'){statsPanel();return}if(action==='restart'){state={...initial,found:[],visited:[],used:[]};player.x=initial.x;player.y=GROUND;player.vx=player.vy=0;player.onGround=true;state.step=0;enemies.length=0;enemyBlueprint.forEach(e=>mkEnemy(e.x,e.type));bullets.length=enemyBullets.length=particles.length=0;interactables.forEach(i=>i.used=false);gameOver=false;started=true;closeModal();updateQuest();updateHud();save();return}if(action==='title'){closeModal();started=false;gameOver=false;el('titleScreen').classList.remove('hidden');return}if(action.startsWith('ending-')){doEnding(action.slice(7));return}if(action==='sneak'){if(state.stamina<20){notify('NOT ENOUGH STAMINA');return}state.stamina-=20;state.step=3;state.found.push('North Checkpoint');interactables.find(i=>i.type==='checkpoint').used=true;for(const e of enemies.filter(a=>a.type==='soldier'))e.dead=true;closeModal();updateQuest();notify('SLIPPED THROUGH — KEEP LOW');save();return}if(action==='fight'){state.step=3;state.found.push('North Checkpoint');closeModal();updateQuest();notify('THE FIGHT WILL ECHO');save();return}if(action==='craft-bandage'){if(state.scrap<2){notify('NEED 2 SCRAP');return}state.scrap-=2;state.bandage++;notify('FIELD DRESSING CRAFTED');inventoryPanel();return}if(action==='craft-ammo'){if(state.scrap<2){notify('NEED 2 SCRAP');return}state.scrap-=2;state.reserve+=6;notify('6 ROUNDS CRAFTED');inventoryPanel();return}if(action.startsWith('quick-')){useItem(action.slice(6));return}}
69:function useItem(item){if(item==='bandage'){if(state.bandage<=0){notify('NO FIELD DRESSINGS');return}if(state.hp>=100){notify('HEALTH ALREADY FULL');return}state.bandage--;state.hp=Math.min(100,state.hp+35);notify('FIELD DRESSING USED  +35 HEALTH')}if(item==='food'){if(state.food<=0){notify('NO FOOD');return}state.food--;state.hunger=Math.min(100,state.hunger+38);state.stamina=Math.min(100,state.stamina+12);notify('CANNED FOOD EATEN')}if(item==='water'){if(state.water<=0){notify('NO WATER');return}state.water--;state.thirst=Math.min(100,state.thirst+42);notify('WATER CONSUMED')}updateHud();save()}
71:function update(dt){frame++;if(!started||paused)return;dt=Math.min(dt,.035);player.invuln=Math.max(0,player.invuln-dt);player.attack=Math.max(0,player.attack-dt);const left=keys.a||keys.arrowleft,right=keys.d||keys.arrowright;let direction=(right?1:0)-(left?1:0);if(direction){player.facing=direction;player.vx=direction*205;player.walk+=dt*10}else{player.vx*=Math.pow(.001,dt);player.walk*=.8}if((keys.space||keys.w||keys.arrowup)&&player.onGround){player.vy=-410;player.onGround=false;keys.space=false;keys.w=false;keys.arrowup=false}if(keys.shift&&direction&&state.stamina>0){player.vx=direction*295;state.stamina=Math.max(0,state.stamina-dt*14)}else state.stamina=Math.min(100,state.stamina+dt*9);player.vy+=960*dt;player.x=clamp(player.x+player.vx*dt,35,WORLD-35);player.y+=player.vy*dt;if(player.y>=GROUND){player.y=GROUND;player.vy=0;player.onGround=true}state.hunger=Math.max(0,state.hunger-dt*.17);state.thirst=Math.max(0,state.thirst-dt*.28);state.temp=Math.max(22,state.temp-dt*.012);if(state.hunger<12||state.thirst<12)state.hp=Math.max(0,state.hp-dt*.38);if(state.hp<=0&&!gameOver)endGame();for(const e of enemies){if(e.dead){e.fade+=dt;continue}const dx=player.x-e.x,dist=Math.abs(dx);if(dist<410)e.alert=Math.min(1,e.alert+dt*1.7);else e.alert=Math.max(0,e.alert-dt*.15);if(e.alert>.4&&dist>50&&!(e.type==='soldier'&&dist<280)){e.dir=Math.sign(dx);e.x+=e.dir*e.speed*dt*(e.alert>.8?1.3:1)}e.attack=Math.max(0,e.attack-dt);if(e.type==='soldier'&&e.alert>.65&&dist<290&&e.attack<=0){enemyBullets.push({x:e.x,y:e.y-39,vx:Math.sign(dx)*310,life:1});e.attack=1.5}else if(dist<50&&e.attack<=0){damage(e.type==='mutant'?19:e.type==='soldier'?11:9,e.type==='mutant'?'MUTANT':e.type==='soldier'?'GUNFIRE':'INFECTED');e.attack=e.type==='mutant'?1.3:1.55}}for(let n=bullets.length-1;n>=0;n--){const b=bullets[n];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;let hit=false;for(const e of enemies){if(e.dead)continue;if(Math.abs(e.x-b.x)<(e.type==='mutant'?25:18)&&b.y>GROUND-e.h&&b.y<GROUND-10){e.hp-=e.type==='mutant'?30:42;for(let i=0;i<5;i++)addParticle(e.x,e.y-35,'#9b5544',3,(Math.random()-.5)*60,-Math.random()*40);if(e.hp<=0)killEnemy(e);hit=true;break}}if(hit||b.life<=0||b.x<0||b.x>WORLD)bullets.splice(n,1)}for(let n=enemyBullets.length-1;n>=0;n--){const b=enemyBullets[n];b.x+=b.vx*dt;b.life-=dt;if(Math.abs(b.x-player.x)<18&&Math.abs(b.y-(player.y-38))<24){damage(13,'GUNFIRE');enemyBullets.splice(n,1)}else if(b.life<=0)enemyBullets.splice(n,1)}for(let n=particles.length-1;n>=0;n--){const p=particles[n];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=70*dt;p.life-=dt;if(p.life<=0)particles.splice(n,1)}autosave+=dt;if(autosave>12){autosave=0;save()}updateHud()}
72:function endGame(){if(gameOver)return;gameOver=true;showModal(`<div class="modal-kicker">DAY 06 · OUTER DISTRICT</div><h1>THE WORLD GOES QUIET</h1><p>Mara's field log ends here. The signal continues to transmit into the rain.</p><div class="modal-actions">${panelButton('LOAD LAST SAVE','restart')}${panelButton('RETURN TO TITLE','title','secondary')}</div>`)}
73:function pauseGame(){if(!started||gameOver)return;if(paused){closeModal();return}showModal(`<button class="modal-close" data-action="resume">×</button><div class="modal-kicker">FIELD LOG · DAY 06</div><h1>PAUSED</h1><p>The rain keeps falling. Take a moment, survivor.</p><div class="modal-actions">${panelButton('RESUME','resume')}${panelButton('INVENTORY','inventory','secondary')}${panelButton('SAVE FIELD LOG','save','secondary')}${panelButton('RETURN TO TITLE','title','secondary')}</div>`)}
79:function handleKeyDown(event){const key=event.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup','arrowdown','tab'].includes(key))event.preventDefault();if(event.repeat)return;if(key==='escape'||key==='p'){pauseGame();return}if(paused||!started)return;keys[key===' '?'space':key]=true;if(key==='e')interact();else if(key==='r')reload();else if(key==='f')melee();else if(key==='1')useItem('bandage');else if(key==='2')useItem('food');else if(key==='3')useItem('water');else if(key==='tab')openPanel('inventory');else if(key==='j')openPanel('journal');else if(key==='m')openPanel('map')}
84:document.addEventListener('click',event=>{const action=event.target.closest('[data-action]');if(action){event.preventDefault();const name=action.dataset.action;if(name==='resume'){closeModal();return}if(name==='save'){save();notify('FIELD LOG SAVED');closeModal();return}performAction(name);return}const panel=event.target.closest('[data-panel]');if(panel){openPanel(panel.dataset.panel);return}const quick=event.target.closest('[data-quick]');if(quick){useItem(quick.dataset.quick);return}if(event.target===el('screenOverlay')&&!gameOver)closeModal()});

