const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.connectOverCDP('http://127.0.0.1:9222'); const context=browser.contexts()[0]; const page=await context.newPage();
 const errors=[];page.on('pageerror',e=>errors.push(e.message));const report=[];
 await page.setViewportSize({width:1440,height:900});await page.goto('http://127.0.0.1:8765');
 await page.evaluate(()=>localStorage.clear());await page.reload();await page.locator('#startBtn').click();
 async function status(){return await page.evaluate(()=>{const s=JSON.parse(localStorage.getItem('ashes-save'));return {x:Math.round(s.x),step:s.step,hp:Math.round(s.hp),bandage:s.bandage,thirst:Math.round(s.thirst),water:s.water}})}
 async function travelTo(targetName){await page.keyboard.down('d');let reached=false;for(let n=0;n<1000;n++){const prompt=await page.locator('#interactionPrompt').innerText();if(prompt.includes(targetName)){reached=true;break}if(await page.locator('#screenOverlay.open').count())break;const s=await status();if(s.hp<70&&s.bandage>0){await page.keyboard.press('1');await page.waitForTimeout(80)}if(s.thirst<18&&s.water>0)await page.keyboard.press('3');await page.waitForTimeout(50)}await page.keyboard.up('d');await page.waitForTimeout(200);return {reached,prompt:await page.locator('#interactionPrompt').innerText(),quest:await page.locator('#questTitle').innerText(),state:await status()}}
 async function interact(label){await page.keyboard.press('e');await page.waitForTimeout(300);const text=await page.locator('#modal').innerText().catch(()=> '');report.push(`${label}: ${text.slice(0,125).replace(/\n/g,' | ')}`)}
 report.push('start '+JSON.stringify(await status()));
 report.push('relay arrival '+JSON.stringify(await travelTo('EMERGENCY RELAY')));await interact('relay');await page.locator('[data-action="close"]').first().click();
 report.push('medic arrival '+JSON.stringify(await travelTo('ELI — WANDERING MEDIC')));await interact('medic');await page.locator('[data-action="close"]').first().click();
 report.push('checkpoint arrival '+JSON.stringify(await travelTo('MILITARY CHECKPOINT')));await interact('checkpoint');
 const choices=await page.locator('.modal [data-action]').evaluateAll(bs=>bs.map(b=>b.dataset.action));report.push('checkpoint options '+JSON.stringify(choices));
 if(await page.locator('[data-action="sneak"]').count())await page.locator('[data-action="sneak"]').click();else await page.locator('[data-action="fight"]').click();
 report.push('blacksite arrival '+JSON.stringify(await travelTo('BLACKSITE ACCESS')));await interact('blacksite');await page.locator('[data-action="close"]').first().click();
 report.push('vault arrival '+JSON.stringify(await travelTo('CONTAINMENT VAULT')));await interact('vault');report.push('ending choices '+await page.locator('[data-action^="ending-"]').count());
 if(await page.locator('[data-action="ending-cure"]').count())await page.locator('[data-action="ending-cure"]').click();
 report.push('ending result '+(await page.locator('#modal').innerText()).slice(0,180).replace(/\n/g,' | '));
 report.push('final save '+JSON.stringify(await status().then(s=>({...s,choice:null,kills:null}))));
 report.push('runtime errors '+JSON.stringify(errors));await browser.close();console.log(JSON.stringify(report,null,2));
})().catch(e=>{console.error(e);process.exit(1)});

